{
  "summary": "Définir le problème de minimax et construire un instrument pour calculer les gains pour chaque allocation possible",
  "actions": [
    {
      "tool": "construct_instrument",
      "name": "minimax_calculator",
      "spec": {
        "inputs": ["allocation", "scenario"],
        "name": "MinimaxCalculator",
        "outputs": {
          "gain": {
            "args": [
              {
                "field": "allocation"
              },
              {
                "field": "scenario"
              }
            ],
            "op": "if"
          }
        }
      }
    },
    {
      "tool": "run_instrument",
      "name": "minimax_calculator",
      "input": {
        "allocation": 1,
        "scenario": "alpha"
      }
    },
    {
      "tool": "run_instrument",
      "name": "minimax_calculator",
      "input": {
        "allocation": 0,
        "scenario": "alpha"
      }
    },
    {
      "tool": "run_instrument",
      "name": "minimax_calculator",
      "input": {
        "allocation": 1,
        "scenario": "beta"
      }
    },
    {
      "tool": "run_instrument",
      "name": "minimax_calculator",
      "input": {
        "allocation": 0,
        "scenario": "beta"
      }
    }
  ],
  "done": false
}
